-- Periodic review schedules. A schedule never grants record or field access.
-- Deprecated schedules stay stored and are ignored when due records are evaluated.
-- Starting a review writes the existing review submission tables; it does not add a decision store.
ALTER TABLE hs_data_schema_dependencies DROP CONSTRAINT IF EXISTS hs_data_schema_dependencies_kind_check;
ALTER TABLE hs_data_schema_dependencies ADD CONSTRAINT hs_data_schema_dependencies_kind_check CHECK(kind IN ('view','import-mapping','integration','reference-policy','template','intake','review','quality','periodic-review'));
CREATE TABLE IF NOT EXISTS hs_data_periodic_review_catalogues(tenant_id uuid NOT NULL,collection text NOT NULL,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_periodic_review_schedules(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,collection text NOT NULL,name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 100),name_search text GENERATED ALWAYS AS(lower(name)) STORED,version integer NOT NULL DEFAULT 1 CHECK(version>0),deprecated boolean NOT NULL DEFAULT false,definition jsonb NOT NULL,created_by text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,collection,name_search),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
ALTER TABLE hs_data_schema_dependencies ADD COLUMN IF NOT EXISTS periodic_schedule_id uuid;
ALTER TABLE hs_data_schema_dependencies DROP CONSTRAINT IF EXISTS hs_data_schema_dependencies_periodic_schedule_id_fkey;
ALTER TABLE hs_data_schema_dependencies ADD CONSTRAINT hs_data_schema_dependencies_periodic_schedule_id_fkey FOREIGN KEY(periodic_schedule_id) REFERENCES hs_data_periodic_review_schedules(id);
CREATE INDEX IF NOT EXISTS hs_data_periodic_review_catalogue ON hs_data_periodic_review_schedules(tenant_id,collection,name_search,id) WHERE deprecated=false;
CREATE TABLE IF NOT EXISTS hs_data_periodic_review_versions(tenant_id uuid NOT NULL,schedule_id uuid NOT NULL,version integer NOT NULL,name text NOT NULL,deprecated boolean NOT NULL,definition jsonb NOT NULL,schema_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,schedule_id,version),FOREIGN KEY(tenant_id,schedule_id) REFERENCES hs_data_periodic_review_schedules(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_periodic_review_operations(tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,schedule_id uuid NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,schedule_id) REFERENCES hs_data_periodic_review_schedules(tenant_id,id));
DROP TRIGGER IF EXISTS hs_data_periodic_review_versions_immutable ON hs_data_periodic_review_versions;
CREATE TRIGGER hs_data_periodic_review_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_periodic_review_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
DROP TRIGGER IF EXISTS hs_data_periodic_review_operations_immutable ON hs_data_periodic_review_operations;
CREATE TRIGGER hs_data_periodic_review_operations_immutable BEFORE UPDATE OR DELETE ON hs_data_periodic_review_operations FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
CREATE OR REPLACE FUNCTION hs_data_periodic_review_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.collection<>OLD.collection OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Periodic review schedule identity and collection are immutable'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS hs_data_periodic_review_identity_guard ON hs_data_periodic_review_schedules;
CREATE TRIGGER hs_data_periodic_review_identity_guard BEFORE UPDATE ON hs_data_periodic_review_schedules FOR EACH ROW EXECUTE FUNCTION hs_data_periodic_review_identity_guard();
